python3 << 'EOF'
import subprocess
import tempfile
import os

device_id = "5C289AD0-4CCF-4724-A5D0-892C8706C76D"

# Create a simple Objective-C program that can scroll the Settings table
objc_code = """
#import <Foundation/Foundation.h>
#import <UIKit/UIKit.h>

int main(int argc, char *argv[]) {
    @autoreleasepool {
        // Try to get the main window and scroll it
        UIApplication *app = [UIApplication sharedApplication];
        UIWindow *mainWindow = app.keyWindow;

        if (mainWindow) {
            // Find the first UITableView
            for (UIView *view in mainWindow.subviews) {
                if ([view isKindOfClass:[UITableView class]]) {
                    UITableView *tableView = (UITableView *)view;
                    // Scroll down
                    [tableView setContentOffset:CGPointMake(0, tableView.contentSize.height - tableView.bounds.size.height) animated:NO];
                    NSLog(@"Scrolled table view");
                    break;
                }
            }
        }
    }
    return 0;
}
"""

# Write the code to a file
with tempfile.NamedTemporaryFile(mode='w', suffix='.m', delete=False) as f:
    f.write(objc_code)
    objc_file = f.name

print(f"Created Objective-C file: {objc_file}")

# Try to compile it
compile_result = subprocess.run([
    "clang", "-fobjc-arc", "-framework", "UIKit", "-framework", "Foundation",
    objc_file, "-o", "/tmp/scroll_settings"
], capture_output=True, text=True)

if compile_result.returncode == 0:
    print("Compilation successful!")
    # Try to run it on the device
    result = subprocess.run([
        "xcrun", "simctl", "spawn", device_id,
        "/tmp/scroll_settings"
    ], capture_output=True, text=True)
    print(f"Execution result: {result.returncode}")
else:
    print(f"Compilation failed: {compile_result.stderr[:200]}")

# Clean up
os.unlink(objc_file)

